  "marker": "TASK_COMPLETE",
  "answer": {
    "summary": "Tesla originally reported revenue using only the legacy US‑GAAP concept 'Revenues'. Beginning in 2018, after adopting ASC 606, Tesla started tagging the same revenue figures with both the legacy concept and the newer ASC 606 concept 'RevenueFromContractWithCustomerExcludingAssessedTax'. The two concepts usually contain identical values for the same period, showing they represent the same revenue figure; thus either can be used from 2018 onward, with the ASC 606 concept preferred for current analysis, while for 2011‑2017 only the legacy concept exists.",
    "claims": [
      {
        "text": "For fiscal years 2011‑2017 Tesla reported revenue solely using the 'Revenues' concept (zero ASC 606 facts).",
        "evidence": ["E-a6bd98", "E-763045"]
      },
      {
        "text": "Starting in fiscal year 2018 Tesla reported both 'Revenues' and 'RevenueFromContractWithCustomerExcludingAssessedTax' concepts.",
        "evidence": ["E-a6bd98", "E-844982"]
      },
      {
        "text": "In filings where both concepts appear, the values are often identical, indicating they capture the same revenue figure (e.g., accession 0001564590-18-011086: Revenues 3408751000 = ASC 606 3408751000).",
        "evidence": ["E-844982"]
      },
      {
        "text": "Therefore, for 2018 onward either concept can be used as they are equivalent; the ASC 606 concept aligns with the current standard and is preferred, while for 2011‑2017 only the legacy 'Revenues' concept exists and should be used.",
        "evidence": ["E-a6bd98", "E-763045", "E-844982"]
      }
    ],
    "inferences": [
      {
        "text": "The occasional non‑matching values within the same accession number reflect different reporting periods (e.g., quarter vs. year‑to‑date) rather than different revenue scopes.",
        "basis": ["Claim 3 (identical values for same period) and the presence of multiple values per accession in E-844982"]
      }
    ],
    "hypothesis_verdicts": [
      {
        "id": "H-3b9440",
        "status": "supported",
        "evidence": ["E-0e3ef9", "E-763045", "E-a6bd98"],
        "why": "Shows legacy concept used early, ASC 606 appears only from 2018 onward."
      },
      {
        "id": "H-d0b0d7",
        "status": "refuted",
        "evidence": ["E-d1d862"],
        "why": "Accession numbers with both concepts are not amended filings (no /A)."
      },
      {
        "id": "H-e2ec90",
        "status": "refuted",
        "evidence": ["E-844982"],
        "why": "Values sometimes equal, sometimes differ in both directions; not consistent with a fixed scope difference."
      },
      {
        "id": "H-5e94de",
        "status": "refuted",
        "evidence": ["E-0e3ef9", "E-d1d862"],
        "why": "Duplicate tagging persists after 2018 and is not random errors; pattern aligns with standard adoption."
      }
    ]
  },
  "carryover": {
    "COMPLETED": "All hypotheses evaluated; determined reason for dual concept usage and appropriate concept per year.",
    "REMAINING": "None",
    "DECISIONS": "Use legacy 'Revenues' for 2011‑2017; from 2018 onward either concept works, prefer ASC 606 for new analysis.",
    "CONTEXT": "Evidence shows ASC 606 adoption in 2018 with parallel tagging; values generally match, indicating same revenue figure."
  }
}
